-- DOCUMENTATION ONLY. PostgreSQL 16. Never execute from this project.
-- ids are generated by the application (no DB defaults).

-- A membership links an external user (user_id, owned by the identity system) to one clinic with ONE role.
CREATE TABLE memberships (
  clinic_id          uuid NOT NULL REFERENCES clinics (id),
  id                 uuid NOT NULL,
  user_id            uuid NOT NULL,
  full_name          text NOT NULL,
  email              text NOT NULL,
  role_id            uuid NOT NULL,
  all_branches       boolean NOT NULL,
  status             text NOT NULL CHECK (status IN ('active','invited','deactivated')),
  preferred_language text NOT NULL CHECK (preferred_language IN ('ar','en')),
  created_at         timestamptz NOT NULL,
  updated_at         timestamptz NOT NULL,
  PRIMARY KEY (clinic_id, id),
  UNIQUE (clinic_id, user_id),
  FOREIGN KEY (clinic_id, role_id) REFERENCES roles (clinic_id, id)
);
CREATE INDEX memberships_clinic_role_idx ON memberships (clinic_id, role_id);
CREATE INDEX memberships_clinic_status_idx ON memberships (clinic_id, status);

ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY memberships_tenant_isolation ON memberships
  USING (clinic_id = current_setting('app.clinic_id')::uuid)
  WITH CHECK (clinic_id = current_setting('app.clinic_id')::uuid);
